// ── GATE 1: API Key Authentication ──────────────────────────────────────────
const headers = $input.first().json.headers ?? {};

function readAgencyAuthHeader(h) {
  const bag = h ?? {};
  const direct = bag['x-agency-auth'] ?? bag['X-Agency-Auth'] ?? bag['X-AGENCY-AUTH'];
  if (direct != null && String(direct).trim()) return String(direct).trim();
  for (const [key, value] of Object.entries(bag)) {
    if (key && key.toLowerCase() === 'x-agency-auth') {
      const v = String(value ?? '').trim();
      if (v) return v;
    }
  }
  return '';
}

const incoming = readAgencyAuthHeader(headers);
const expected = String($env?.DASHBOARD_AUTH_KEY ?? '').trim();

if (!expected) {
  throw new Error('AUTH_FAIL: DASHBOARD_AUTH_KEY is not configured');
}

if (!incoming || incoming !== expected) {
  throw new Error('AUTH_FAIL: Invalid or missing x-agency-auth header');
}

// ── GATE 2: Rate Limiting ─────────────────────────────────────────────────────
if (!global._dashboardRateLimit) {
  global._dashboardRateLimit = { count: 0, windowStart: Date.now() };
}

const rl      = global._dashboardRateLimit;
const now     = Date.now();
const WINDOW  = 5 * 60 * 1000;  // 5 minutes
const MAX_REQ = 30;

if (now - rl.windowStart > WINDOW) {
  rl.count       = 0;
  rl.windowStart = now;
}

rl.count++;

if (rl.count > MAX_REQ) {
  throw new Error(`RATE_LIMIT: ${rl.count} requests in 5-min window (max ${MAX_REQ})`);
}

// ── GATE 3: Serve from cache if fresh ────────────────────────────────────────
const CACHE_TTL_MS = 60_000; 

if (
  global._dashboardCache &&
  global._dashboardCache.data &&
  (now - global._dashboardCache.fetchedAt) < CACHE_TTL_MS
) {
  return [{
    json: {
      _fromCache:  true,
      _cacheAgeMs: now - global._dashboardCache.fetchedAt,
      ...global._dashboardCache.data
    }
  }];
}

return [{ json: { _fromCache: false } }];

// ── Transform & Validate Google Sheets rows → typed KPI object ───────────────
//
// EXPECTED SHEET STRUCTURE (tab: Calculs, range A1:B30)
//   Row 1 : header  →  Metric | Valeur
//   Row 2 : patients_today  | <COUNTIFS formula result>
//   Row 3 : no_shows        | <COUNTIFS formula result>
//   Row 4 : revenue_today   | <SUMIFS formula result>
//   Row 5 : new_patients    | <COUNTIFS formula result>
//   Row 6 : accepted_plans  | <COUNTIF formula result>
//   Row 7 : pending_plans   | <COUNTIF formula result>
//   Row 8-18 : hour_08 through hour_18 (one per hour)
//
// SCHEMA: these are the only metric names the dashboard trusts.
// Any key not in this set is stripped from the output (defence-in-depth).

const NUMERIC_METRICS = new Set([
  'patients_today',
  'no_shows',
  'revenue_today',
  'new_patients',
  'accepted_plans',
  'pending_plans',
  'hour_08', 'hour_09', 'hour_10', 'hour_11', 'hour_12',
  'hour_13', 'hour_14', 'hour_15', 'hour_16', 'hour_17', 'hour_18',
]);

const STRING_METRICS = new Set([
  // reserved for future string metrics, e.g. next_patient_name
]);

const ALL_METRICS = new Set([...NUMERIC_METRICS, ...STRING_METRICS]);

// Safe parse: coerce to number, fallback to 0
function safeNum(v) {
  if (v === null || v === undefined || v === '') return 0;
  const n = Number(String(v).replace(/\s/g, '').replace(',', '.'));
  return isFinite(n) ? n : 0;
}

const rows   = $input.all();
const result = {};
const errors = [];

for (const r of rows) {
  const raw = r.json ?? {};

  // Normalise column name capitalisation:
  // Sheets may return 'Metric'/'Valeur' or 'metric'/'valeur' depending on
  // sheet locale and n8n version.
  const metricKey = (
    raw['Metric'] ?? raw['metric'] ?? raw['METRIC'] ?? ''
  ).toString().trim();

  const rawValue = raw['Valeur'] ?? raw['valeur'] ?? raw['VALEUR'] ?? '';

  // Skip empty / header rows
  if (!metricKey || metricKey === 'Metric') continue;

  // Skip unknown metrics (schema guard)
  if (!ALL_METRICS.has(metricKey)) {
    errors.push(`Unknown metric ignored: '${metricKey}'`);
    continue;
  }

  // Type coercion
  if (NUMERIC_METRICS.has(metricKey)) {
    result[metricKey] = safeNum(rawValue);
  } else {
    result[metricKey] = String(rawValue).trim();
  }
}

// Fill any missing metrics with safe defaults so the dashboard
// always gets a complete object — never undefined keys.
for (const m of NUMERIC_METRICS) {
  if (!(m in result)) {
    result[m] = 0;
    errors.push(`Missing metric in Sheets: '${m}' — defaulted to 0`);
  }
}

// Schema validation summary
if (errors.length > 0) {
  console.warn('[Dashboard] Schema warnings:', errors.join(' | '));
}

// Timezone-aware timestamp (Africa/Casablanca)
const now = new Date();
const fetchedAt = now.toLocaleString('fr-MA', {
  timeZone: 'Africa/Casablanca',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
});

// Update in-process cache
if (!global._dashboardCache) global._dashboardCache = {};
global._dashboardCache.fetchedAt = Date.now();
global._dashboardCache.data = {
  ...result,
  last_updated:    fetchedAt,
  schema_warnings: errors,
};

return [{  json: {
    ...result,
    last_updated:    fetchedAt,
    _fromCache:      false,
    schema_warnings: errors,
  }
}];

// ── Merge cache-hit path and fresh-fetch path ────────────────────────────────
// Both the cache-hit branch (true branch of IF) and the fresh-fetch branch
// (Transform & Validate) merge here before responding.
// This node just passes through — it exists to give the Merge a clear name.

const item = $input.first();
const payload = item.json;

// Add a trace/request ID for debugging
const traceId = `dash-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;

return [{
  json: {
    ok:          true,
    trace_id:    traceId,
    from_cache:  payload._fromCache ?? false,
    ...payload,
  }
}];

// ── Error Handler: build a structured error response ─────────────────────────
// This node fires when Auth + Rate Limit throws (AUTH_FAIL / RATE_LIMIT)
// OR when Get Dashboard KPIs / Transform nodes throw.
// It NEVER exposes internal stack traces to the client.

const err      = $input.first()?.json ?? {};
const errMsg   = (err.message ?? err.error ?? 'Internal error').toString();
const isAuth   = errMsg.startsWith('AUTH_FAIL');
const isRate   = errMsg.startsWith('RATE_LIMIT');

// Log full error internally
console.error('[Dashboard] Error:', errMsg);

const now = new Date().toLocaleString('fr-MA', {
  timeZone: 'Africa/Casablanca',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
});

return [{
  json: {
    httpStatus: isAuth ? 401 : isRate ? 429 : 503,
    body: {
      ok:          false,
      error:       isAuth ? 'Unauthorized'
                 : isRate ? 'Too Many Requests'
                 : 'Service temporarily unavailable',
      message:     isAuth ? 'Invalid or missing x-agency-auth header'
                 : isRate ? 'Rate limit exceeded. Retry in 5 minutes.'
                 : 'Could not read data from Google Sheets. Retry in 30 seconds.',
      timestamp:   now,
      trace_id:    `err-${Date.now().toString(36)}`,
    }
  }
}];
